// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNum, uint256 blockTimestamp) public {
        vm.assume(blockNum > 0);
        vm.assume(blockTimestamp > 0);
        vm.roll(blockNum);
        vm.warp(blockTimestamp);
        address sender = address(0x1);
        vm.deal(sender, 20 ether);
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 10 ether}("");
        vm.assume(success);
        bool isDivisibleBy15 = (blockNum % 15 == 0);
        bool balanceZero = address(c).balance == 0;
        assertTrue(balanceZero == isDivisibleBy15);
    }
}
